import { defineMiddleware } from 'astro:middleware';

// Headers for every response the Worker produces (pages and API). The Content-Security-Policy itself is
// generated by Astro (security.csp in astro.config.mjs) so it can hash Astro's own inline scripts.
const SECURITY_HEADERS: Record<string, string> = {
  // List links carry secret tokens in the URL; never send them to other sites in a Referer header.
  'referrer-policy': 'no-referrer',
  'x-content-type-options': 'nosniff',
  // Belt and braces with CSP frame-ancestors, for older browsers: nobody may embed this app in a frame.
  'x-frame-options': 'DENY',
  'strict-transport-security': 'max-age=31536000; includeSubDomains',
  'permissions-policy': 'camera=(), microphone=(), geolocation=(), payment=(), usb=()',
  'cross-origin-opener-policy': 'same-origin',
};

export const onRequest = defineMiddleware(async (_context, next) => {
  const response = await next();
  // Some responses (e.g. from fetch()) have immutable headers, so rebuild the response to be safe.
  const out = new Response(response.body, response);
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) out.headers.set(name, value);
  // HTML pages for /l/<token> must not sit in shared or browser caches.
  if ((out.headers.get('content-type') ?? '').includes('text/html') && !out.headers.has('cache-control')) {
    out.headers.set('cache-control', 'private, no-store');
  }
  return out;
});
